package com.iare.club.service;
import com.iare.club.entity.MerchantPaymentConfig;import java.math.BigDecimal;import java.time.Instant;import org.junit.jupiter.api.*;import org.springframework.http.*;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestClient;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;
class YoupiGatewayClientTest{
 RestClient.Builder builder;MockRestServiceServer server;YoupiGatewayClient client;
 @BeforeEach void setup(){builder=RestClient.builder();server=MockRestServiceServer.bindTo(builder).build();client=new YoupiGatewayClient(builder,"https://youpi.test","merchant-1","secret-key","admin-token",true);}
 @Test void createsActualYoupiPaymentWithServerCredentialsAndIdempotency(){server.expect(requestTo("https://youpi.test/api/v1/payments")).andExpect(method(HttpMethod.POST)).andExpect(header("X-Merchant-Id","merchant-1")).andExpect(header("X-Merchant-Key","secret-key")).andExpect(header("Idempotency-Key","UPI123")).andExpect(content().json("{\"orderId\":\"UPI123\",\"amount\":\"100.00\",\"currency\":\"INR\",\"method\":\"UPI\"}",false)).andRespond(withSuccess("{\"paymentId\":\"yp-1\",\"checkoutUrl\":\"https://pay.test/checkout/yp-1\",\"status\":\"INITIATED\"}",MediaType.APPLICATION_JSON));var result=client.createPayment("UPI123",new BigDecimal("100.00"),"https://fundrise.test/deposit");assertThat(result.paymentId()).isEqualTo("yp-1");server.verify();}
 @Test void synchronizesAdminUpiSettingsToYoupi(){server.expect(requestTo("https://youpi.test/api/v1/admin/upi-settings")).andExpect(method(HttpMethod.POST)).andExpect(header(HttpHeaders.AUTHORIZATION,"Bearer admin-token")).andExpect(content().json("{\"merchantId\":\"merchant-1\",\"upiId\":\"merchant@upi\",\"payeeName\":\"FundRise\",\"isMerchantEnabled\":true}",true)).andRespond(withSuccess("{}",MediaType.APPLICATION_JSON));client.updateUpiSettings(new MerchantPaymentConfig("FundRise","merchant@upi","Not specified",null,true,"admin",Instant.now()));server.verify();}
}
